package Arrays;

public class SecondProgram {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		int a[]= {1,2,3,4};
		for(int i=0;i<a.length;i++) {
			System.out.print(a[i]+" ");
		}
		System.out.println();
		for(int ele:a) {
			System.out.print(ele+" ");
		}

	}

}
